"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7100],{97100:a=>{a.exports=JSON.parse('{"slug":"dollar-86-rubley-minfin-pokupki-valyuty","locale":"zh","title":"美元升破86卢布：财政部外汇购买量扩大5倍","description":"十月6日美元突破86卢布。财政部从十月7日起每天购买12.7十亿卢布外汇；分析油价如何通过预算规则削弱卢布。","blocks":[{"id":"b001","kind":"paragraph","text":"十月6日上午，场外市场美元最高86.1卢布，自九月9日以来首次超过86。欧元涨0.6%至96.3，人民币涨0.7%至12.8卢布。央行官方汇率依据前一日交易，因此十月6日较低，为84.93卢布，较前一天高1.45；十月1日为83.56。全球美元在十月5日反而下跌，说明卢布走弱有本地原因。"},{"id":"b002","kind":"paragraph","text":"财政部十月5日宣布，在十月7日至十一月6日期间购买279.42十亿卢布外汇与黄金，每天12.7十亿。上月每天仅2.5十亿。央行同时每天出售0.58十亿卢布外汇，扣除后国家净购买12.12十亿，九月为1.92十亿，相差6.3倍，为2022年初以来最大。购买尚未开始，要到十月7日，但市场已对公告反应。"},{"id":"b003","kind":"paragraph","text":"资金来自石油。俄罗斯预算以Urals每桶$59为基准；超出时，差额税收不花掉，而通过购买外汇和黄金存入国家福利基金，这一门槛称为截断油价。石油企业缴税滞后一个月，十月缴九月税。八月Urals为$67.11，略高于门槛；九月$92.08，所以十月财政部预计超计划收入289.46十亿卢布。实际购买279.42十亿，是扣除了10.04十亿，因为九月收入低于先前估计。"},{"id":"b004","kind":"paragraph","text":"规则本身本不该改变卢布：石油企业为缴更高税出售更多外汇，财政部再买回。问题在时点。财政部从十月7日起每天等额购买，出口商则在月底缴税前集中卖汇。月初数周买方多于卖方，卢布便贬值。中国假期持续至十月7日，人民币交易少，大额买单更容易推动汇率。"},{"id":"b005","kind":"paragraph","text":"卢布继续走弱会传到依赖外汇的旅游、电子设备和汽车价格。十月1日至6日官方美元汇率已上升1.6%。支撑卢布的是央行14%的关键利率，使卢布存款比外币存款更有吸引力。月底出口商卖汇缴税通常也支撑卢布，但能抵消财政部多少购买，目前无法判断。"},{"id":"b006","kind":"paragraph","text":"准备换外汇的人要看期限。当前汇率受每月购买计划抬升，该轮在十一月6日结束。但若十月油价继续高企，十一月购买仍会很大，因为十一月税款按十月油价计算。"},{"id":"b007","kind":"heading","text":"美元为何在2026年十月上涨？"},{"id":"b008","kind":"paragraph","text":"财政部从十月7日起每天买12.7十亿卢布外汇与黄金，是九月的5倍。大买家推动外汇价格，公告即触发反应：十月6日美元自九月9日以来首次升破86卢布。"},{"id":"b009","kind":"heading","text":"预算规则中的截断油价是什么？"},{"id":"b010","kind":"paragraph","text":"这是预算基准油价，2026年为每桶$59。高于此价的石油税收不用于支出，而通过购买外汇与黄金存入国家福利基金。"},{"id":"b011","kind":"heading","text":"财政部会按这一规模买多久？"},{"id":"b012","kind":"paragraph","text":"当前规模适用于十月7日至十一月6日。新规模将在十一月初公布，取决于十月油价。"}],"sources":[{"label":"财政部从十月7日起将外汇与黄金购买扩大五倍","url":"https://www.interfax.ru/business/1120386"},{"label":"财政部十月7日至十一月6日购买279.42十亿卢布外汇与黄金","url":"https://www.kommersant.ru/doc/9006327"},{"label":"财政部与央行十月外汇净购买扩大逾6倍","url":"https://ru.themoscowtimes.com/2026/10/05/update-1-minfin-i-tsbr-narastyat-pokupki-valyuty-v-oktyabre-bolee-chem-v-6-raz-do-1212-mlrd-r-v-den-a207802"},{"label":"美元自九月9日以来首次突破86卢布","url":"https://www.kommersant.ru/doc/9007053"},{"label":"卢布早盘兑人民币走弱","url":"https://www.interfax.ru/business/1120563"},{"label":"央行将官方美元汇率上调近1.5卢布","url":"https://finance.mail.ru/article/tsb-povyisil-ofitsialnyij-kurs-dollara-pochti-na-15-69231003/"},{"label":"官方美元汇率跌破84卢布","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"石油收入采用新的截断价格","url":"https://www.fontanka.ru/2026/09/09/76634061/"},{"label":"九月Urals在波罗的海、印度和中国涨价","url":"https://www.interfax.ru/business/1119753"},{"label":"降息预期回升，美股走强而美元波动","url":"https://finance.yahoo.com/markets/stocks/articles/stocks-upbeat-dollar-wobbles-fed-012516671.html"},{"label":"俄罗斯央行维持关键利率14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"b900eb1904932c64959784d06618a3e247429cc6ba8713c6bd8f0558bb9d2f88"}')}}]);